import * as K from './skills.js?v=36';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const covered=new Set(['Doctor','Engineer','Place Deployable','Reload','Baggage','360º Visor','Mimetism','Discover','Sensor','Camouflage','Surprise Attack','Stealth','Sixth Sense','Combat Instinct','Multispectral Visor','Triangulated Fire','Martial Arts','BS Attack','Dodge','Reset','Move','Idle','CC Attack','Climb','Climbing Plus','Jump','Super-Jump','Remote Presence','Tactical Awareness','Marksmanship','X-Visor','Limited Cover','No Cover','Total Reaction','Warhorse','Natural Born Warrior']);
export function catalogHTML(catalog){return `<h2>技能与装备 · ${catalog.entries.length} 项</h2><p>N5.3 / FAQ V0.1 · 18 通用技能、78 特殊技能、26 装备。来源目录已逐项读取；“已接入”仅指本页列出的判定范围，完整例外仍以链接原文为准。“规则参考”尚未自动结算，不会静默套用。</p><label>搜索技能<input id="skillSearch" type="search" placeholder="360、拟态、发现、Sensor…"></label><div class="skillCatalog">${catalog.entries.map(e=>`<article data-skill-search="${esc((e.zh+' '+e.en).toLowerCase())}"><h3>${esc(e.zh)} <small>${esc(e.en)}</small></h3><span class="skillCoverage">${covered.has(e.en)?'已接入核心判定':'规则参考 · 未自动结算'}</span><p>${esc(e.summary)}</p><a href="${e.source}" target="_blank" rel="noreferrer">官方 N5.3 原文 ↗</a></article>`).join('')}</div>`;}
export function unitSkillsHTML(u,busy){if(u.armyLocked)return `<div class="skillBadges">${K.summary(u).map(n=>`<span>${esc(n.replace('（教学覆写）',''))}</span>`).join('')}</div><details><summary>官方配置 · 已锁定技能</summary><p>${esc(u.officialAbilities.join(' / ')||'无额外技能')}</p><p class="micro">只能使用该配置具备且已接入的技能；教学开关不可修改导入配置。</p>${u.unsupported?.length?`<p class="warning">未自动实现：${esc(u.unsupported.join('；'))}</p>`:''}</details>`;return `<div class="skillBadges">${K.summary(u).map(n=>`<span>${esc(n)}</span>`).join('')||'<span>无额外技能修正</span>'}</div><details><summary>技能配置与适配范围</summary><p class="helper">初始配置来自此单位的 Army 条目；修改开关属于教学覆写。${esc((u.officialAbilities||[]).join(' / '))}</p><div class="skillChecks">${Object.entries(K.SKILL_FIELDS).map(([k,n])=>`<label><input data-skill="${k}" type="checkbox" ${u[k]?'checked':''} ${busy?'disabled':''}>${n}</label>`).join('')}</div><div class="editgrid">${[['msv','多光谱等级',0,3],['mim','拟态（负修正绝对值）',0,6],['bsMod','自身 BS 修正',-12,12],['bsAttackNegative','BS Attack 对手负修正',-12,0],['surpriseAttack','突袭负修正绝对值',0,6],['martialArts','武术等级',0,5],['bsBurstBonus','BS 主动额外 B',0,2],['dodgeDistanceBonus','闪避额外英寸',0,4]].map(([k,n,min,max])=>`<label>${n}<input type="number" data-skill-number="${k}" value="${u[k]||0}" min="${min}" max="${max}" ${busy?'disabled':''}></label>`).join('')}</div><button id="toggleCamo" class="wide" ${busy||!u.camouflage?'disabled':''}>${K.marker(u)?'教学：移除迷彩标记':'教学：设置迷彩标记'}</button><p class="micro">教学状态开关不消耗命令。对局中使用“重新迷彩”整令并检查敌方视线／Sensor。黑客已接入自身及有效友方中继器控制区的聚光、碳化、遗忘、三位一体攻击；敌方中继器路线、全面控制、支援程序、完整火力组、载具、空降与复杂地形等条目仍为规则参考，不会声称已自动实现。</p></details>`;}
